import React, { useState, useEffect } from "react";
import api from "../../api";

const Artikel = () => {
  const [data, setData] = useState([]);
  const [showModal, setShowModal] = useState(false);
  const [formData, setFormData] = useState({
    judul: "",
    categori: "",
    content: "",
    gambar: null
  });

  useEffect(() => {
    api.get('/artikel')
      .then(response => {
        setData(response.data);
      })
      .catch(error => {
        console.error("Error fetching data:", error);
      });
  }, []);

  const handleOpenModal = () => {
    setShowModal(true);
    setFormData({
      judul: "",
      categori: "",
      content: "",
      gambar: null
    });
  };

  const handleCloseModal = () => {
    setShowModal(false);
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleFileChange = (e) => {
    const file = e.target.files[0];
    setFormData(prev => ({ ...prev, gambar: file }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const formDataToSend = new FormData();
    formDataToSend.append('judul', formData.judul);
    formDataToSend.append('categori', formData.categori);
    formDataToSend.append('content', formData.content);
    if (formData.gambar) formDataToSend.append('gambar', formData.gambar);

    api.post('/artikel', formDataToSend)
      .then(response => {
        setData([...data, response.data]);
        setShowModal(false);
      })
      .catch(error => {
        console.error("Error submitting form:", error);
      });
  };

  return (
    <div>
      <div className="grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        <table className="min-w-full bg-white border border-teal-300 rounded-lg shadow">
          <thead className="bg-teal-700 text-white">
            <tr>
              <th className="px-6 py-3 text-left font-medium">No</th>
              <th className="px-6 py-3 text-left font-medium">Judul</th>
              <th className="px-6 py-3 text-left font-medium">Kategori</th>
              <th className="px-6 py-3 text-left font-medium">Content</th>
              <th className="px-6 py-3 text-left font-medium">Action</th>
            </tr>
          </thead>
          <tbody>
            {data.length > 0 ? (
              data.map((row, index) => (
                <tr key={row.id}>
                  <td className="px-6 py-4">{index + 1}</td>
                  <td className="px-6 py-4">{row.judul}</td>
                  <td className="px-6 py-4">{row.categori}</td>
                  <td className="px-6 py-4">{row.content}</td>
                  <td className="px-6 py-4">
                    <button
                      onClick={handleOpenModal}
                      className="bg-teal-500 text-white py-1 px-3 rounded-lg"
                    >
                      Edit
                    </button>
                  </td>
                </tr>
              ))
            ) : (
              <tr>
                <td colSpan="5" className="text-center px-6 py-4 text-gray-500">
                  Tidak ada jadwal tersedia.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {/* Modal Form */}
      {showModal && (
        <div className="fixed inset-0 bg-gray-500 bg-opacity-50 flex justify-center items-center">
          <div className="bg-white p-6 rounded-lg shadow-lg w-96">
            <h2 className="text-xl font-semibold mb-4">Tambah Artikel</h2>
            <form onSubmit={handleSubmit}>
              <div className="mb-4">
                <label htmlFor="judul" className="block text-sm font-medium mb-2">
                  Judul
                </label>
                <input
                  type="text"
                  id="judul"
                  name="judul"
                  value={formData.judul}
                  onChange={handleInputChange}
                  className="w-full p-2 border border-gray-300 rounded"
                />
              </div>
              <div className="mb-4">
                <label htmlFor="categori" className="block text-sm font-medium mb-2">
                  Kategori
                </label>
                <input
                  type="text"
                  id="categori"
                  name="categori"
                  value={formData.categori}
                  onChange={handleInputChange}
                  className="w-full p-2 border border-gray-300 rounded"
                />
              </div>
              <div className="mb-4">
                <label htmlFor="content" className="block text-sm font-medium mb-2">
                  Content
                </label>
                <textarea
                  id="content"
                  name="content"
                  value={formData.content}
                  onChange={handleInputChange}
                  className="w-full p-2 border border-gray-300 rounded"
                  rows="4"
                />
              </div>
              <div className="mb-4">
                <label htmlFor="gambar" className="block text-sm font-medium mb-2">
                  Gambar
                </label>
                <input
                  type="file"
                  id="gambar"
                  name="gambar"
                  onChange={handleFileChange}
                  className="w-full p-2 border border-gray-300 rounded"
                />
              </div>
              <div className="flex justify-end">
                <button
                  type="button"
                  onClick={handleCloseModal}
                  className="bg-gray-500 text-white py-2 px-4 rounded-lg mr-2"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="bg-teal-500 text-white py-2 px-4 rounded-lg"
                >
                  Submit
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Artikel;
